begin;
set local lock_timeout='5s';
set local statement_timeout='30s';
lock table machimoa_review.source_item_program_facts,machimoa_review.source_item_content_filters,machimoa_review.review_classifications,machimoa_review.review_classification_history in share row exclusive mode;
lock table machimoa_review.myseoul_review_confirmations,machimoa_review.myseoul_confirmation_install in share row exclusive mode;
do $$ declare d text;begin
if (select dirty from machimoa_review.myseoul_confirmation_install where singleton) is distinct from false or exists(select 1 from machimoa_review.myseoul_review_confirmations) then raise exception 'myseoul_confirmation_records_present';end if;
if to_regprocedure('machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'b44ea7d872e39133ed9a5291a279dbd893f829c3cd2f28bb4dffc7209435200f' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.myseoul_evaluate(jsonb, timestamp with time zone)';end if;
if to_regprocedure('machimoa_review.classification_reasons(uuid, jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.classification_reasons(uuid, jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'79c14dcfc779abd549d6b96dafb0d4a59e8264fd391d595ef0b54be14c23a24b' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.classification_reasons(uuid, jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.classification_reasons(uuid, jsonb)';end if;
if to_regprocedure('public.admin_myseoul_program_detail(uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.admin_myseoul_program_detail(uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'349b4d67fc6da33709f637009af5ff0c03eb0bf46f618bfc7e0b5de27ea2b2d3' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.admin_myseoul_program_detail(uuid)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','public.admin_myseoul_program_detail(uuid)';end if;
if to_regprocedure('machimoa_review.myseoul_reason_fields(text)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_reason_fields(text)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'34efa4fac23acbbfdbd8b49ebfceb3219445c5c5e3993d91fcaee09aece1ded9' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_reason_fields(text)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.myseoul_reason_fields(text)';end if;
if to_regprocedure('machimoa_review.myseoul_region_confirmed(jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_region_confirmed(jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'89de89d3c1a8da7ddde20da309ccfab8b471338463e24321cd0123007dcdb620' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_region_confirmed(jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.myseoul_region_confirmed(jsonb)';end if;
if to_regprocedure('machimoa_review.myseoul_body_confirmed(jsonb)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_body_confirmed(jsonb)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'499c57963d2fef72883807e51fe27be7902cfc4b7ee727d50f9918556d4c2fc8' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_body_confirmed(jsonb)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.myseoul_body_confirmed(jsonb)';end if;
if to_regprocedure('machimoa_review.myseoul_review_body_ready(uuid,text)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_review_body_ready(uuid,text)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'3c3b711062f4c8cc61d5fb91bc7cf9cf0cfb7bc431e020751366ccbc46aee5f3' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_review_body_ready(uuid,text)')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.myseoul_review_body_ready(uuid,text)';end if;
if to_regprocedure('public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'4ea7eeb2d033ff3aef34d75d062f4fecfdf55b044e992cc663092c8aa970befa' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid)';end if;
if to_regprocedure('public.admin_myseoul_body_confirm(uuid,text,text,text,uuid)') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('public.admin_myseoul_body_confirm(uuid,text,text,text,uuid)')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'48eb83fdbed4e3f1938fe47124aabc11737537cf92d58b5a07de600cff660790' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('public.admin_myseoul_body_confirm(uuid,text,text,text,uuid)')) is distinct from '{"acl": ["postgres=X/postgres", "service_role=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": true}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','public.admin_myseoul_body_confirm(uuid,text,text,text,uuid)';end if;
if to_regprocedure('machimoa_review.myseoul_confirmation_dirty()') is null or encode(sha256(convert_to(replace(replace(pg_get_functiondef(to_regprocedure('machimoa_review.myseoul_confirmation_dirty()')),E'\r\n',E'\n'),E'\r',E'\n'),'UTF8')),'hex')<>'82a2a51479ee21f6bc3f41384d7ab954c40e13ba2cc179948f2ed2b9818b3d92' or (select jsonb_build_object('owner',pg_get_userbyid(proowner),'acl',proacl,'config',proconfig,'definer',prosecdef) from pg_proc where oid=to_regprocedure('machimoa_review.myseoul_confirmation_dirty()')) is distinct from '{"acl": ["postgres=X/postgres"], "owner": "postgres", "config": ["search_path=\"\""], "definer": false}'::jsonb then raise exception 'myseoul_confirmation_successor_changed: %','machimoa_review.myseoul_confirmation_dirty()';end if;
if (select encode(sha256(convert_to(backup::text,'UTF8')),'hex') from machimoa_review.myseoul_confirmation_install)<>'bcf0ec65ad2bb3c7f1f6bd56485bfb770722fab14c85faabf742db3abf234f7c' then raise exception 'myseoul_confirmation_backup_changed';end if;
if not (select relrowsecurity from pg_class where oid='machimoa_review.myseoul_confirmation_install'::regclass) or exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_table_privilege(r,'machimoa_review.myseoul_confirmation_install','SELECT,INSERT,UPDATE,DELETE')) then raise exception 'myseoul_confirmation_table_changed';end if;
if not (select relrowsecurity from pg_class where oid='machimoa_review.myseoul_review_confirmations'::regclass) or exists(select 1 from unnest(array['anon','authenticated','service_role']) r where has_table_privilege(r,'machimoa_review.myseoul_review_confirmations','SELECT,INSERT,UPDATE,DELETE')) then raise exception 'myseoul_confirmation_table_changed';end if;
if (select count(*) from pg_trigger where tgname='myseoul_confirmation_dirty' and tgfoid='machimoa_review.myseoul_confirmation_dirty()'::regprocedure and tgenabled='O' and not tgisinternal and tgtype=28 and tgrelid in ('machimoa_review.source_item_program_facts'::regclass,'machimoa_review.source_item_content_filters'::regclass,'machimoa_review.review_classifications'::regclass,'machimoa_review.review_classification_history'::regclass,'machimoa_review.myseoul_review_confirmations'::regclass))<>5 then raise exception 'myseoul_confirmation_trigger_changed';end if;
for d in select value#>>'{}' from machimoa_review.myseoul_confirmation_install cross join lateral jsonb_each(backup) loop execute d;end loop;
end $$;
drop trigger myseoul_confirmation_dirty on machimoa_review.source_item_program_facts;
drop trigger myseoul_confirmation_dirty on machimoa_review.source_item_content_filters;
drop trigger myseoul_confirmation_dirty on machimoa_review.review_classifications;
drop trigger myseoul_confirmation_dirty on machimoa_review.review_classification_history;
drop trigger myseoul_confirmation_dirty on machimoa_review.myseoul_review_confirmations;
drop function machimoa_review.myseoul_confirmation_dirty();
drop function public.admin_myseoul_body_confirm(uuid,text,text,text,uuid);
drop function public.admin_myseoul_activity_confirm(uuid,text,text,bigint,jsonb,jsonb,uuid);
drop function machimoa_review.myseoul_review_body_ready(uuid,text);
drop function machimoa_review.myseoul_body_confirmed(jsonb);
drop function machimoa_review.myseoul_region_confirmed(jsonb);
drop table machimoa_review.myseoul_review_confirmations;
drop table machimoa_review.myseoul_confirmation_install;
commit;
